/// CLI args for `status`.
#[derive(Args, Debug)]
pub struct StatusArgs {
    /// Workspace root or single jj repo path [default: the workspace
    /// around the current directory, else .]
    #[arg(short = 'R', long = "repo", value_name = "PATH")]
