/// The set directory for one command: the operand as given, else
/// the command's `dir` key, else `family.template`, the config
/// values relative to `root`, the config file's directory. An
/// error names the three when none is set, and the path when the
/// directory is missing.
pub fn resolve_set_dir(
    root: &Path,
    operand: Option<&Path>,
    key: &'static str,
    key_value: Option<&str>,
    template: Option<&str>,
) -> Result<(PathBuf, DirSource), Box<dyn std::error::Error>> {
