    fn diff(&self) -> Result<bool, Box<dyn std::error::Error>> {
        let root = common::find_workspace_root().ok_or("not in a vc-x1 workspace")?;
        let cfg = super::config_at(&root)?;
        let template = crate::config_md::load(&root)?
            .and_then(|c| crate::toml_simple::toml_get(&c.map, "family.template").cloned());
