#[cfg(test)]
mod tests {
    use super::*;
    use clap::Parser;

    #[derive(Parser)]
    struct T {
        #[command(flatten)]
        a: DiffArgs,
    }

    /// A set directory under the test tmp root with the given
    /// files, `(relative path, content)`.
    fn set_dir(tag: &str, files: &[(&str, &str)]) -> PathBuf {
        let dir = crate::test_tmp_root::resolve_tmp_root().join(format!("vc_x1_af_diff_{tag}"));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join(AGENT_DATA)).expect("mkdir");
        for (path, content) in files {
            std::fs::write(dir.join(path), content).expect("write");
        }
        dir
    }

    /// The flags parse, and `-c` with `--no-custom` is refused.
    #[test]
    fn flags_parse() {
        let a = T::try_parse_from(["t", "../x", "-c"]).unwrap().a;
        assert_eq!(a.dir, Some(PathBuf::from("../x")));
        assert!(a.custom && !a.no_custom);
        let a = T::try_parse_from(["t", "--no-custom"]).unwrap().a;
        assert!(a.dir.is_none() && a.no_custom);
        assert!(T::try_parse_from(["t", "-c", "--no-custom"]).is_err());
    }

    /// Flag, then key, then default, in that order.
    #[test]
    fn custom_resolution_order() {
        assert!(resolve_custom(true, false, Some(false), false));
        assert!(!resolve_custom(false, true, Some(true), true));
        assert!(resolve_custom(false, false, Some(true), false));
        assert!(!resolve_custom(false, false, None, false));
        assert!(resolve_custom(false, false, None, true));
    }

    /// Operand, then the key, then family.template, each relative
    /// to the config's directory, and a clear error with none or
    /// with a path that is not a directory.
    #[test]
    fn set_dir_resolution_order() {
        let root = set_dir("root", &[]);
        let peer = set_dir("peer", &[]);
        let tpl = set_dir("tpl", &[]);
        let key = "agent-files.diff.dir";
        let (d, s) = resolve_set_dir(&root, Some(&peer), key, Some("../nope"), None).unwrap();
        assert_eq!((d, s), (peer.clone(), DirSource::Operand));
        let rel = format!("../{}", peer.file_name().unwrap().to_str().unwrap());
        let (d, s) = resolve_set_dir(&root, None, key, Some(&rel), Some("../x")).unwrap();
        assert_eq!(d.canonicalize().unwrap(), peer.canonicalize().unwrap());
        assert_eq!(s, DirSource::ConfigKey(key));
        let rel = format!("../{}", tpl.file_name().unwrap().to_str().unwrap());
        let (d, s) = resolve_set_dir(&root, None, key, None, Some(&rel)).unwrap();
        assert_eq!(d.canonicalize().unwrap(), tpl.canonicalize().unwrap());
        assert_eq!(s, DirSource::FamilyTemplate);
        let err = resolve_set_dir(&root, None, key, None, None).unwrap_err();
        assert!(err.to_string().contains("family.template"), "{err}");
        let err = resolve_set_dir(&root, None, key, Some("../missing-dir"), None).unwrap_err();
        assert!(err.to_string().contains("not a directory"), "{err}");
    }

    /// Every state appears: same, differs, only on each side, and
    /// custom.md as the project layer until `-c` compares it. The
    /// summary counts what was compared, and the report aligns.
    #[test]
    fn compare_states_and_report() {
        let here = set_dir(
            "here",
            &[
                ("AGENTS.md", "rules\n"),
                ("custom.md", "mine\n"),
                ("agent-data/a.md", "same\n"),
                ("agent-data/b.md", "old\n"),
                ("agent-data/agent-files-v0.1.0", ""),
            ],
        );
        let there = set_dir(
            "there",
            &[
                ("AGENTS.md", "rules\n"),
                ("custom.md", "theirs\n"),
                ("agent-data/a.md", "same\n"),
                ("agent-data/b.md", "new\n"),
                ("agent-data/c.md", "extra\n"),
            ],
        );
        let rows = compare(&here, &there, false).unwrap();
        assert_eq!(
            rows,
            vec![
                ("AGENTS.md".to_string(), State::Same),
                ("agent-data/a.md".to_string(), State::Same),
                ("agent-data/agent-files-v0.1.0".to_string(), State::OnlyHere),
                ("agent-data/b.md".to_string(), State::Differs),
                ("agent-data/c.md".to_string(), State::OnlyThere),
                ("custom.md".to_string(), State::ProjectLayer),
            ]
        );
        let text = report(&rows, "../there");
        assert!(text.contains("agent-data/c.md                 only in ../there\n"), "{text}");
        assert!(text.contains("custom.md                       project layer"), "{text}");
        assert!(text.ends_with("3 of 5 differ\n"), "{text}");
        let rows = compare(&here, &there, true).unwrap();
        assert!(rows.contains(&("custom.md".to_string(), State::Differs)));
        assert!(report(&rows, "x").ends_with("4 of 6 differ\n"));
        let rows = compare(&here, &here, true).unwrap();
        assert!(rows.iter().all(|(_, s)| *s == State::Same));
        assert!(report(&rows, "x").ends_with("0 of 5 differ\n"));
    }
}
