//! `agent-files copy [DIR]`: make this workspace's set a byte copy
//! of the one in DIR, inbound only, and leave it uncommitted.
//!
//! - `CopyArgs`: clap surface, the `DIR` operand and the
//!   `-c`/`--custom` / `--no-custom` pair, as `diff` has them.
//! - `plan`: what a copy would do, from `diff::compare`'s rows:
//!   copy what differs or is only there, delete what is only here,
//!   and never touch custom.md unless asked, or TODO.md at all.
//! - `apply`: do it. The working copy must be clean in the set's
//!   paths first, so the copy's changes are the only ones there
//!   and a `jj diff` reads as the re-sync.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::Args;
use log::{error, info};

use super::diff::{self, AGENT_DATA, State};
use crate::common;

/// CLI args for `agent-files copy`.
#[derive(Args, Debug)]
pub struct CopyArgs {
    /// A directory holding a copy of the set [default:
    /// agent-files.copy.dir, else family.template]
    #[arg(value_name = "DIR")]
    pub dir: Option<PathBuf>,

    /// Copy custom.md with the rest of the set
    #[arg(short = 'c', long = "custom", conflicts_with = "no_custom")]
    pub custom: bool,

    /// Leave custom.md alone, overriding agent-files.copy.custom
    #[arg(long = "no-custom")]
    pub no_custom: bool,
}

/// One step of a copy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Step {
    Copy(String),
    Delete(String),
}

impl std::fmt::Display for Step {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Step::Copy(p) => write!(f, "copy   {p}"),
            Step::Delete(p) => write!(f, "delete {p}"),
        }
    }
}

/// The steps that make `here`'s set equal to `there`'s, in path
/// order: a copy for each file that differs or exists only there,
/// a delete for each that exists only here. Nothing for the
/// project layer when it is not asked for.
pub fn plan(here: &Path, there: &Path, custom: bool) -> Result<Vec<Step>, Box<dyn std::error::Error>> {
    Ok(diff::compare(here, there, custom)?
        .into_iter()
        .filter_map(|(path, state)| match state {
            State::Differs | State::OnlyThere => Some(Step::Copy(path)),
            State::OnlyHere => Some(Step::Delete(path)),
            State::Same | State::ProjectLayer => None,
        })
        .collect())
}

/// Run the steps: copy creates `agent-data/` when it is missing,
/// delete removes the file only.
pub fn apply(here: &Path, there: &Path, steps: &[Step]) -> Result<(), Box<dyn std::error::Error>> {
    for step in steps {
        match step {
            Step::Copy(path) => {
                if let Some(parent) = here.join(path).parent() {
                    std::fs::create_dir_all(parent)?;
                }
                std::fs::copy(there.join(path), here.join(path))
                    .map_err(|e| format!("copy {path}: {e}"))?;
            }
            Step::Delete(path) => {
                std::fs::remove_file(here.join(path)).map_err(|e| format!("delete {path}: {e}"))?;
            }
        }
    }
    Ok(())
}

/// True when `path` is one the copy may touch: AGENTS.md, anything
/// under `agent-data/`, and custom.md when `custom`.
fn in_set(path: &str, custom: bool) -> bool {
    path == diff::AGENTS_MD
        || path.starts_with(&format!("{AGENT_DATA}/"))
        || (custom && path == diff::CUSTOM_MD)
}

/// The working copy's changed paths inside the set, which a copy
/// would mix its own changes with.
fn dirty_set_paths(root: &Path, custom: bool) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    Ok(crate::jj::wc_status(root)?
        .changes
        .into_iter()
        .filter(|(_, p)| in_set(p, custom))
        .map(|(letter, p)| format!("{letter} {p}"))
        .collect())
}

impl CopyArgs {
    /// Run the copy in the workspace around the current directory.
    pub fn run(&self) -> ExitCode {
        match self.copy() {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                error!("agent-files copy: {e}");
                ExitCode::FAILURE
            }
        }
    }

    /// Resolve, guard, print the plan, apply it.
    fn copy(&self) -> Result<(), Box<dyn std::error::Error>> {
        let root = common::find_workspace_root().ok_or("not in a vc-x1 workspace")?;
        let cfg = super::config_at(&root)?;
        let template = crate::config_md::load(&root)?
            .and_then(|c| crate::toml_simple::toml_get(&c.map, "family.template").cloned());
        let dir = diff::resolve_set_dir(
            &root,
            self.dir.as_deref(),
            "agent-files.copy.dir",
            cfg.copy.dir.as_deref(),
            template.as_deref(),
        )?;
        let custom = diff::resolve_custom(
            self.custom,
            self.no_custom,
            cfg.copy.custom,
            crate::config_schema::AGENT_FILES_COPY_CUSTOM_DEFAULT,
        );
        if dir.path.canonicalize()? == root.canonicalize()? {
            return Err(format!("'{}' is this workspace: nothing to copy from", dir.shown).into());
        }
        info!(
            "agent-files copy: from {} ({}) into {}{}",
            dir.shown,
            dir.source,
            root.display(),
            if custom { ", custom.md included" } else { "" }
        );
        let dirty = dirty_set_paths(&root, custom)?;
        if !dirty.is_empty() {
            return Err(format!(
                "the working copy already changes the set, commit or restore first:\n  {}",
                dirty.join("\n  ")
            )
            .into());
        }
        let steps = plan(&root, &dir.path, custom)?;
        if steps.is_empty() {
            info!("already the same, nothing to do");
            return Ok(());
        }
        for step in &steps {
            info!("{step}");
        }
        apply(&root, &dir.path, &steps)?;
        info!(
            "{} step(s) applied, left uncommitted for review",
            steps.len()
        );
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_helpers::Fixture;
    use clap::Parser;

    #[derive(Parser)]
    struct T {
        #[command(flatten)]
        a: CopyArgs,
    }

    /// Write `(relative path, content)` files under `dir`.
    fn seed(dir: &Path, files: &[(&str, &str)]) {
        std::fs::create_dir_all(dir.join(AGENT_DATA)).expect("mkdir");
        for (path, content) in files {
            std::fs::write(dir.join(path), content).expect("write");
        }
    }

    /// The flags parse, and `-c` with `--no-custom` is refused.
    #[test]
    fn flags_parse() {
        let a = T::try_parse_from(["t", "../x", "--custom"]).unwrap().a;
        assert_eq!(a.dir, Some(PathBuf::from("../x")));
        assert!(a.custom);
        assert!(T::try_parse_from(["t", "-c", "--no-custom"]).is_err());
    }

    /// A copy plan copies what differs or is only there, deletes what
    /// is only here, and leaves custom.md and TODO.md alone until
    /// `-c` brings custom.md in. Applied, the sets compare equal.
    #[test]
    fn plan_and_apply_mirror_the_set() {
        let base = crate::test_helpers::unique_base("af-copy");
        let here = base.join("here");
        let there = base.join("there");
        seed(
            &here,
            &[
                ("AGENTS.md", "old rules\n"),
                ("custom.md", "mine\n"),
                ("TODO.md", "my todo\n"),
                ("agent-data/a.md", "same\n"),
                ("agent-data/stale.md", "gone\n"),
            ],
        );
        seed(
            &there,
            &[
                ("AGENTS.md", "new rules\n"),
                ("custom.md", "theirs\n"),
                ("TODO.md", "their todo\n"),
                ("agent-data/a.md", "same\n"),
                ("agent-data/b.md", "new\n"),
            ],
        );
        let steps = plan(&here, &there, false).unwrap();
        assert_eq!(
            steps,
            vec![
                Step::Copy("AGENTS.md".to_string()),
                Step::Copy("agent-data/b.md".to_string()),
                Step::Delete("agent-data/stale.md".to_string()),
            ]
        );
        assert_eq!(steps[0].to_string(), "copy   AGENTS.md");
        assert_eq!(steps[2].to_string(), "delete agent-data/stale.md");
        apply(&here, &there, &steps).unwrap();
        let rows = diff::compare(&here, &there, false).unwrap();
        assert!(rows.iter().all(|(_, s)| !s.differs()), "{rows:?}");
        assert_eq!(std::fs::read_to_string(here.join("custom.md")).unwrap(), "mine\n");
        assert_eq!(std::fs::read_to_string(here.join("TODO.md")).unwrap(), "my todo\n");
        assert!(plan(&here, &there, false).unwrap().is_empty());
        let steps = plan(&here, &there, true).unwrap();
        assert_eq!(steps, vec![Step::Copy("custom.md".to_string())]);
        apply(&here, &there, &steps).unwrap();
        assert_eq!(std::fs::read_to_string(here.join("custom.md")).unwrap(), "theirs\n");
        let _ = std::fs::remove_dir_all(&base);
    }

    /// A working copy that already changes a set file is refused,
    /// naming the change, and one that changes only other files is
    /// not. custom.md counts only when it is being copied.
    #[test]
    fn dirty_guard_sees_only_the_set() {
        let fx = Fixture::new("af-copy-guard");
        seed(
            &fx.work,
            &[
                ("AGENTS.md", "rules\n"),
                ("custom.md", "mine\n"),
                ("agent-data/a.md", "a\n"),
            ],
        );
        crate::jj::commit(&fx.work, "test: seed the set").unwrap();
        assert!(dirty_set_paths(&fx.work, false).unwrap().is_empty());
        std::fs::write(fx.work.join("README.md"), "other\n").unwrap();
        std::fs::write(fx.work.join("custom.md"), "edited\n").unwrap();
        assert!(dirty_set_paths(&fx.work, false).unwrap().is_empty());
        assert_eq!(
            dirty_set_paths(&fx.work, true).unwrap(),
            vec!["M custom.md".to_string()]
        );
        std::fs::write(fx.work.join("agent-data/a.md"), "b\n").unwrap();
        assert_eq!(
            dirty_set_paths(&fx.work, false).unwrap(),
            vec!["M agent-data/a.md".to_string()]
        );
    }
}
